script:
// Material Request Title 自动生成脚本
// 根据 items 的商品信息自动生成 Title

// 触发时机：保存 Material Request 时
// 如果 title 已存在且不为空，则不覆盖
if (doc.title && doc.title.trim() !== '') {
    return;
}

// 获取 items 列表
let items = doc.items || [];
if (items.length === 0) {
    return;
}

// 限制显示的物品数量，避免 title 过长
const maxItems = 3;
let displayItems = items.slice(0, maxItems);

// 收集商品名称（优先使用 item_name，如果没有则使用 item_code）
let itemNames = [];
for (let i = 0; i < displayItems.length; i++) {
    let item = displayItems[i];
    let itemName = item.item_name || item.item_code || '';

    // 限制每个商品名称的长度
    if (itemName.length > 20) {
        itemName = itemName.substring(0, 20);
    }

    if (itemName) {
        itemNames.push(itemName);
    }
}

if (itemNames.length === 0) {
    return;
}

// 生成 title 格式: "Purchase Request for {item1}, {item2}, {item3}"
let title = "Purchase Request for " + itemNames[0];
for (let i = 1; i < itemNames.length; i++) {
    title += ", " + itemNames[i];
}

// 如果还有更多物品，添加省略号
if (items.length > maxItems) {
    title += "...";
}

// 设置 title
cur_frm.set_value('title', title);
